<?php $siteId=(int)$profile['id']; $sitePath='/websites/'.$siteId; $collectionId=$collection['id'] ?? ''; $capabilities=$collection['capabilities'] ?? []; $display=static function($value):string { return is_bool($value) ? ($value ? 'Yes' : 'No') : (is_scalar($value) || $value===null ? (string)$value : json_encode($value,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)); }; ?>
