</div><div><form class="stack" action="<?= e($sitePath) ?>/login" method="post"><?= csrf_field() ?><label>Username<input name="username" maxlength="120" autocomplete="username" required></label><label>Password<span class="website-password-field"><input name="password" type="password" maxlength="4096" autocomplete="current-password" required><button class="website-password-toggle" type="button" data-website-password aria-label="Show password" aria-pressed="false">Show</button></span></label><button <?= !$profile['connector_url'] ? 'disabled' : '' ?>>Sign in &amp; open admin panel</button></form>
<details><summary>Advanced: connect with an API token</summary><form class="stack" action="<?= e($sitePath) ?>/connect" method="post" autocomplete="off"><?= csrf_field() ?><label>Connector token<input name="token" type="password" minlength="32" maxlength="4096" autocomplete="off" required></label><button <?= !$profile['connector_url'] ? 'disabled' : '' ?>>Connect with token</button></form></details>
