<?php else: ?><section class="card website-connected-header"><div class="section-heading"><div><h2>Website admin panel</h2><?php if($connection['username'] ?? ''): ?><p class="muted">Signed in as <?= e($connection['username']) ?></p><?php endif; ?><p class="muted">Panel supplied by <?= e($connection['manifest']['site']['name'] ?? $profile['name']) ?> · <?= count($collections) ?> collections</p></div><form method="post" action="<?= e($sitePath) ?>/disconnect"><?= csrf_field() ?><button class="secondary">Sign out of this website</button></form></div><p class="footnote">Only actions declared by the connected site are shown. Remote changes happen when you submit a save or delete action.</p></section>
