<?php if($collection): ?><section class="card"><div class="section-heading"><div><h2><?= e($collection['label']) ?></h2><p class="muted"><?= $cached ? e($cached['total']).' records · Last loaded '.e($cached['fetched_at']) : 'Records have not been loaded in this session.' ?></p></div><form action="<?= e($sitePath) ?>/refresh" method="post"><?= csrf_field() ?><input type="hidden" name="collection" value="<?= e($collectionId) ?>"><input type="hidden" name="offset" value="<?= e($cached['offset'] ?? 0) ?>"><button class="secondary">Load / refresh</button></form></div>
<?php if($cached && !$cached['records']): ?><p class="muted">No records returned by this website.</p><?php endif; ?>
<?php foreach($cached['records'] ?? [] as $record): ?><article class="lesson-entry"><div class="section-heading"><strong><?= e($record['data'][$collection['fields'][0]['name']] ?? $record['id']) ?></strong><small>Version <?= e($record['version']) ?></small></div><dl class="website-record-values"><?php foreach($collection['fields'] as $field): ?><div><dt><?= e($field['label']) ?></dt><dd><?= e(mb_strimwidth($display($record['data'][$field['name']] ?? ''),0,300,'…')) ?></dd></div><?php endforeach; ?></dl><div class="hero-actions"><?php if(in_array('update',$capabilities,true)): ?><a href="<?= e($sitePath) ?>?collection=<?= e(rawurlencode($collectionId)) ?>&amp;edit=<?= e(rawurlencode((string)$record['id'])) ?>#record-form">Edit record</a><?php endif; ?><?php if(in_array('delete',$capabilities,true)): ?><form action="<?= e($sitePath) ?>/record/delete" method="post" data-confirm="Delete this record from the connected website? This changes remote data."><?= csrf_field() ?><input type="hidden" name="collection" value="<?= e($collectionId) ?>"><input type="hidden" name="record_id" value="<?= e($record['id']) ?>"><input type="hidden" name="version" value="<?= e($record['version']) ?>"><button class="delete">Delete from website</button></form><?php endif; ?></div></article><?php endforeach; ?>
<?php if($cached): ?><div class="hero-actions"><?php foreach(['Previous'=>max(0,$cached['offset']-$cached['limit']),'Next'=>$cached['offset']+$cached['limit']] as $label=>$offset): if(($label==='Previous' && $cached['offset']===0) || ($label==='Next' && $offset>=$cached['total']))continue; ?><form action="<?= e($sitePath) ?>/refresh" method="post"><?= csrf_field() ?><input type="hidden" name="collection" value="<?= e($collectionId) ?>"><input type="hidden" name="offset" value="<?= e($offset) ?>"><button class="secondary"><?= e($label) ?></button></form><?php endforeach; ?></div><?php endif; ?></section>
<?php if(($edit && in_array('update',$capabilities,true)) || (!$edit && in_array('create',$capabilities,true))): ?><section class="card" id="record-form"><h2><?= $edit ? 'Edit record' : 'Add record' ?></h2><form class="form-grid" method="post" action="<?= e($sitePath) ?>/record"><?= csrf_field() ?><input type="hidden" name="collection" value="<?= e($collectionId) ?>"><?php if($edit): ?><input type="hidden" name="record_id" value="<?= e($edit['id']) ?>"><input type="hidden" name="version" value="<?= e($edit['version']) ?>"><?php endif; ?>
<?php foreach($collection['fields'] as $field): $name='fields['.$field['name'].']';$value=$edit['data'][$field['name']] ?? ''; $required=!empty($field['required']); ?><label class="<?= $field['type']==='textarea' ? 'full' : '' ?>"><?= e($field['label']) ?><?= $required ? ' *' : '' ?>
<?php if($field['type']==='textarea'): ?><textarea name="<?= e($name) ?>" rows="5" maxlength="<?= e($field['max_length'] ?? 10000) ?>" <?= $required ? 'required' : '' ?>><?= e($value) ?></textarea>
<?php elseif($field['type']==='boolean'): ?><input type="hidden" name="<?= e($name) ?>" value="0"><input name="<?= e($name) ?>" type="checkbox" value="1" <?= $value ? 'checked' : '' ?>>
<?php else: ?><input name="<?= e($name) ?>" type="<?= e(in_array($field['type'],['number','date'],true) ? $field['type'] : 'text') ?>" <?= $field['type']==='number' ? 'step="any"' : '' ?> maxlength="<?= e($field['max_length'] ?? 2000) ?>" value="<?= e($value) ?>" <?= $required ? 'required' : '' ?>><?php endif; ?></label><?php endforeach; ?>
<div class="full"><button><?= $edit ? 'Save changes to website' : 'Create on website' ?></button><?php if($edit): ?> <a href="<?= e($sitePath) ?>?collection=<?= e(rawurlencode($collectionId)) ?>">Cancel edit</a><?php endif; ?></div></form><p class="footnote">Version checks prevent silently overwriting a record changed by another editor. Refresh the page if the remote version has changed.</p></section><?php endif; ?>
<?php endif; ?></div></div><?php endif; ?>
